def robot_hint(c,part):
    if not c.get('config',{}).get('fixed_saved_route_priors') or not c['config'].get('fixed_supply_mode'):return None
    arm=c['arm'];g={k:np.round(np.asarray(getattr(arm,k)),9).tolist() for k in ['base','tip','frames','axes','bounds']}
    if hashlib.sha256(json.dumps(g,sort_keys=True).encode()).hexdigest()!=DATA['robot_geometry_sha256']:return None
    here=Path(__file__).resolve().parent
    if any(hashlib.sha256((here/name).read_bytes()).hexdigest()!=digest for name,digest in DATA['native_geometry_sha256'].items()):return None
    return DATA['parts'].get(part)
def route_hint(c,key,start,goal):
    if not c.get('config',{}).get('fixed_saved_route_priors') or not c['config'].get('fixed_supply_mode'):return None
    values=DATA['routes'].get(key)
    if values is None:return None
    q=np.asarray(values,float).copy()
    if max(np.max(abs(q[0]-start)),np.max(abs(q[-1]-goal)))>.75:return None
    q[0]=start;q[-1]=goal
    return q
